import java.util.*;
class Solution {
    public int minProcessingTime(List<Integer> processorTime, List<Integer> tasks) {
        List<Integer> t = new ArrayList<>(tasks);
        t.sort(Collections.reverseOrder());
        List<Integer> ps = new ArrayList<>(processorTime);
        Collections.sort(ps);
        long lo = ps.get(ps.size()-1) + Collections.min(t), hi = ps.get(ps.size()-1) + Collections.max(t);
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            int j = 0; boolean ok = true;
            for (int p : ps) {
                long cap = mid - p; int used = 0;
                while (j < t.size() && used < 4 && t.get(j) <= cap) { j++; used++; }
                if (used == 0) { ok = false; break; }
            }
            if (ok && j == t.size()) hi = mid; else lo = mid + 1;
        }
        return (int) lo;
    }
}

