var minProcessingTime = function(processorTime, tasks) {
    const t = [...tasks].sort((a,b)=>b-a);
    const ps = [...processorTime].sort((a,b)=>a-b);
    const ok = T => {
        let j = 0;
        for (const p of ps) {
            let used = 0;
            while (j < t.length && used < 4 && t[j] <= T - p) { j++; used++; }
            if (!used) return false;
        }
        return j === t.length;
    };
    let lo = ps[ps.length-1] + Math.min(...t), hi = ps[ps.length-1] + Math.max(...t);
    while (lo < hi) { const mid = Math.floor((lo+hi)/2); if (ok(mid)) hi = mid; else lo = mid+1; }
    return lo;
};
